const diary=new Diary();const caps={...capabilities(),...extraCapabilities()};
let favoriteModes=new Set(),homeCategory='all',homeSearch='',mediaURLs=[],previewURL=null,lastMode=null;try{favoriteModes=new Set(JSON.parse(localStorage.getItem('spare-phone-favorites')||'[]'));lastMode=localStorage.getItem('spare-phone-last-mode');}catch{}
