function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function message(text,error=false){const el=$('#message');if(el){el.textContent=text;el.classList.toggle('error',error);}}
function put(selector,text){const el=$(selector);if(el)el.textContent=text;}
async function log(mode,title,detail='',blob=null,filename=null){try{return await diary.write({mode,title,detail,blob,filename});}catch(e){toast(errorText(e));return null;}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
const filename=(mode,ext)=>`spare-phone-${mode}-${new Date().toISOString().replace(/[:.]/g,'-')}.${ext}`;
function extraAPI(){return {$,motionListener,put,message,toast,owned,requestStream,addListener,every,later,log,stopSession,download,filename,icon,jpeg,session:()=>session,route:()=>route};}
function releaseMediaURLs(){mediaURLs.forEach(u=>URL.revokeObjectURL(u));mediaURLs=[];}
function supported(api){return caps[api];}
function modeCard(m){return `<article class="mode-item"><a class="mode-card" data-mode="${m.id}" data-category="${m.category}" href="#${m.id}"><span class="icon">${icon(m.id)}</span><div class="tool-card-copy"><h3>${m.name}</h3>${!supported(m.api)?'<small class="tool-availability">Check support</small>':''}</div><span class="tool-open" aria-hidden="true">${icon('arrow')}</span></a><button class="favorite-button ${favoriteModes.has(m.id)?'saved':''}" data-favorite="${m.id}" aria-label="${favoriteModes.has(m.id)?'Remove':'Add'} ${m.name} ${favoriteModes.has(m.id)?'from':'to'} favorites" aria-pressed="${favoriteModes.has(m.id)}">${icon('star')}</button></article>`;}
function renderCards(){const selected=MODES.filter(m=>(homeCategory==='all'||homeCategory==='favorites'&&favoriteModes.has(m.id)||m.category===homeCategory||homeCategory==='security'&&['camera','tamper','power'].includes(m.id))&&`${m.name} ${m.description} ${m.sensor}`.toLowerCase().includes(homeSearch.toLowerCase()));const grid=$('#tool-grid');grid.innerHTML=selected.length?selected.map(modeCard).join(''):'<div class="empty search-empty"><h3>No tools found</h3><p>Try another search or category.</p><button id="reset-search" class="secondary">Show all tools</button></div>';put('#tool-count',selected.length+' TOOLS');$('#reset-search')?.addEventListener('click',()=>{homeSearch='';homeCategory='all';home();});grid.querySelectorAll('[data-favorite]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.favorite;if(favoriteModes.has(id))favoriteModes.delete(id);else favoriteModes.add(id);try{localStorage.setItem('spare-phone-favorites',JSON.stringify([...favoriteModes]));}catch{}renderCards();}));}
