const UPCOMING=[['noise','Sound-triggered camera','Capture a moment when a sound breaks the quiet.'],['motion','Motion counter','Count repeated movements with your phone.'],['timelapse','Focus timer','Give your old phone a place on your desk.'],['clock','Desk clock','A simple, always-visible clock for your space.']];
function isInstalled(){return matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;}
async function installApp(){const status=$('#install-status');if(isInstalled()){if(status)status.textContent='Spare Phone is already running as an installed app.';return;}if(installEvent){const prompt=installEvent;installEvent=null;try{await prompt.prompt();const result=await prompt.userChoice;if(status)status.textContent=result.outcome==='accepted'?'Installation requested. Open Spare Phone from your home screen.':'You can install later from your browser menu.';}catch{if(status)status.textContent='Open your browser menu and choose Install app or Add to Home screen.';}}else if(status){status.textContent='Android: open the browser menu → Install app or Add to Home screen. iPhone: open in Safari → Share → Add to Home Screen.';status.scrollIntoView({block:'nearest',behavior:'smooth'});}}
