const select=(id,title,options)=>`<label class="field"><span>${title}</span><select id="${id}">${options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;
const slider=(id,title,value,min,max,step=1)=>`<label class="field"><span>${title}<output id="${id}-value">${value}</output></span><input id="${id}" type="range" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
const checkbox=(id,text,checked=false)=>`<label class="check"><input type="checkbox" id="${id}" ${checked?'checked':''}>${text}</label>`;
