 controls=slider('tamper-threshold','Movement threshold (m/s²)',1.4,.5,5,.1)+checkbox('alarm-sound','Play an alarm sound',true)+checkbox('alarm-vibrate','Vibrate if supported',true);steps=['Set your phone down before starting.','Allow motion sensor access if requested.','Wait for the five-second countdown. Leave this page visible.'];
